@@ -1,0 +1,574 @@
+:root {
+  --bg: #0b0b0d;
+  --bg-2: #111114;
+  --bg-3: #16161b;
+  --surface: #1b1b22;
+  --surface-2: #22222b;
+  --border: #2a2a33;
+  --border-strong: #3a3a46;
+  --text: #ececf0;
+  --text-dim: #a8a8b3;
+  --text-muted: #777783;
+  --accent: #d8b46b;
+  --accent-2: #e9c98a;
+  --accent-ink: #1a1306;
+  --danger: #ff6b6b;
+  --success: #6bd39a;
+  --radius: 14px;
+  --radius-lg: 22px;
+  --shadow-1: 0 1px 0 rgba(255,255,255,0.04) inset, 0 10px 30px rgba(0,0,0,0.45);
+  --shadow-2: 0 20px 60px rgba(0,0,0,0.55);
+  --maxw: 1240px;
+  --gap: clamp(16px, 2vw, 28px);
+  --font-sans: "Inter", "Helvetica Neue", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
+  --font-display: "Cormorant Garamond", "Times New Roman", Georgia, serif;
+}
+
+* { box-sizing: border-box; }
+html { scroll-behavior: smooth; }
+body {
+  margin: 0;
+  font-family: var(--font-sans);
+  color: var(--text);
+  background: radial-gradient(1200px 600px at 80% -10%, rgba(216,180,107,0.07), transparent 60%),
+              radial-gradient(900px 500px at -10% 20%, rgba(120,120,200,0.05), transparent 60%),
+              var(--bg);
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+  line-height: 1.55;
+}
+
+img { max-width: 100%; display: block; }
+a { color: inherit; text-decoration: none; }
+a:hover { color: var(--accent-2); }
+ul { margin: 0; padding: 0; list-style: none; }
+button { font: inherit; cursor: pointer; }
+
+/* a11y */
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px; overflow: hidden;
+  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
+}
+.skip-link {
+  position: absolute; top: -40px; left: 12px;
+  background: var(--accent); color: var(--accent-ink);
+  padding: 8px 14px; border-radius: 8px; font-weight: 600; z-index: 100;
+}
+.skip-link:focus { top: 12px; }
+
+:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 3px;
+  border-radius: 6px;
+}
+
+.container { max-width: var(--maxw); margin: 0 auto; padding: 0 clamp(16px, 3vw, 32px); }
+
+/* Header */
+.site-header {
+  position: sticky; top: 0; z-index: 50;
+  background: rgba(11,11,13,0.78);
+  backdrop-filter: saturate(140%) blur(14px);
+  -webkit-backdrop-filter: saturate(140%) blur(14px);
+  border-bottom: 1px solid var(--border);
+}
+.header-inner {
+  display: flex; align-items: center; justify-content: space-between;
+  padding: 16px 0;
+  gap: 24px;
+}
+.brand {
+  display: inline-flex; align-items: center; gap: 10px;
+  font-weight: 700; letter-spacing: 0.14em; font-size: 14px;
+  text-transform: uppercase;
+}
+.brand-mark { color: var(--accent); font-size: 16px; }
+.primary-nav ul { display: flex; gap: 28px; }
+.primary-nav a {
+  font-size: 14px; color: var(--text-dim); padding: 8px 2px;
+  position: relative; transition: color .2s;
+}
+.primary-nav a:hover { color: var(--text); }
+.primary-nav a::after {
+  content: ""; position: absolute; left: 0; right: 100%; bottom: 2px;
+  height: 1px; background: var(--accent); transition: right .25s ease;
+}
+.primary-nav a:hover::after { right: 0; }
+
+.header-actions { display: flex; gap: 6px; }
+.icon-btn {
+  position: relative;
+  width: 40px; height: 40px;
+  display: inline-flex; align-items: center; justify-content: center;
+  background: transparent; color: var(--text);
+  border: 1px solid transparent; border-radius: 10px;
+  transition: background .2s, border-color .2s;
+}
+.icon-btn:hover { background: var(--surface); border-color: var(--border); }
+.badge {
+  position: absolute; top: 4px; right: 4px;
+  min-width: 18px; height: 18px; padding: 0 5px;
+  border-radius: 999px; background: var(--accent); color: var(--accent-ink);
+  font-size: 11px; font-weight: 700; display: inline-flex; align-items: center; justify-content: center;
+}
+
+/* Buttons */
+.btn {
+  display: inline-flex; align-items: center; justify-content: center;
+  padding: 12px 22px; border-radius: 999px;
+  font-size: 14px; font-weight: 600; letter-spacing: 0.02em;
+  border: 1px solid transparent; transition: transform .15s, background .2s, color .2s, border-color .2s;
+  cursor: pointer; text-align: center;
+}
+.btn:hover { transform: translateY(-1px); }
+.btn-primary { background: var(--accent); color: var(--accent-ink); }
+.btn-primary:hover { background: var(--accent-2); color: var(--accent-ink); }
+.btn-ghost { background: transparent; color: var(--text); border-color: var(--border-strong); }
+.btn-ghost:hover { background: var(--surface); color: var(--text); }
+
+/* Section utilities */
+section { padding: clamp(56px, 8vw, 96px) 0; }
+.section-head {
+  display: flex; align-items: end; justify-content: space-between;
+  gap: 24px; margin-bottom: 36px; flex-wrap: wrap;
+}
+.section-head h2 {
+  font-family: var(--font-display);
+  font-size: clamp(28px, 3.6vw, 44px);
+  font-weight: 500; line-height: 1.1; margin: 6px 0 0;
+  letter-spacing: -0.01em;
+}
+.eyebrow {
+  text-transform: uppercase; letter-spacing: 0.18em; font-size: 12px;
+  color: var(--accent); margin: 0;
+}
+.muted { color: var(--text-dim); }
+.small { font-size: 13px; }
+
+.link-arrow {
+  color: var(--text-dim); font-size: 14px; font-weight: 500;
+  border-bottom: 1px solid transparent; padding-bottom: 2px;
+}
+.link-arrow:hover { color: var(--text); border-bottom-color: var(--accent); }
+
+/* Hero */
+.hero { padding-top: clamp(40px, 6vw, 72px); }
+.hero-inner {
+  display: grid; grid-template-columns: 1.1fr 1fr; gap: clamp(24px, 4vw, 64px);
+  align-items: center;
+}
+.hero-copy h1 {
+  font-family: var(--font-display);
+  font-size: clamp(42px, 6.5vw, 92px);
+  font-weight: 500; line-height: 0.98; margin: 14px 0 20px;
+  letter-spacing: -0.02em;
+}
+.hero-copy .lede { font-size: 17px; color: var(--text-dim); max-width: 52ch; }
+.hero-actions { display: flex; gap: 12px; margin: 28px 0 40px; flex-wrap: wrap; }
+
+.hero-meta {
+  display: grid; grid-template-columns: repeat(3, minmax(0,1fr));
+  gap: 18px; margin: 0; padding-top: 28px;
+  border-top: 1px solid var(--border);
+}
+.hero-meta dt { font-size: 13px; color: var(--text); font-weight: 600; }
+.hero-meta dd { margin: 4px 0 0; font-size: 13px; color: var(--text-muted); }
+
+.hero-visual {
+  position: relative;
+  aspect-ratio: 1/1; max-width: 560px; justify-self: end; width: 100%;
+}
+.hero-card {
+  position: absolute; border-radius: var(--radius-lg);
+  border: 1px solid var(--border);
+  box-shadow: var(--shadow-2);
+  overflow: hidden;
+}
+.hero-card-1 {
+  inset: 6% 18% 28% 0;
+  background:
+    radial-gradient(80% 60% at 30% 30%, #3a3a46 0%, #1a1a22 60%, #0e0e13 100%);
+}
+.hero-card-1::after {
+  content: ""; position: absolute; inset: 0;
+  background:
+    linear-gradient(135deg, rgba(216,180,107,.14), transparent 40%),
+    radial-gradient(circle at 70% 70%, rgba(255,255,255,.05), transparent 50%);
+}
+.hero-card-2 {
+  inset: 22% 0 8% 30%;
+  background:
+    linear-gradient(160deg, #2a2218 0%, #1a1410 60%, #0c0a08 100%);
+}
+.hero-card-2::after {
+  content: ""; position: absolute; inset: 0;
+  background: radial-gradient(60% 50% at 50% 40%, rgba(216,180,107,0.25), transparent 70%);
+}
+.hero-card-3 {
+  inset: 56% 50% 0 8%;
+  background:
+    linear-gradient(135deg, #1f2a2a 0%, #121a1a 60%, #0a0f0f 100%);
+}
+.hero-glow {
+  position: absolute; inset: -20%;
+  background: radial-gradient(40% 30% at 60% 40%, rgba(216,180,107,0.18), transparent 70%);
+  pointer-events: none; z-index: -1;
+}
+
+/* Categories */
+.cat-grid {
+  display: grid; gap: var(--gap);
+  grid-template-columns: repeat(5, minmax(0,1fr));
+}
+.cat-tile {
+  display: block; aspect-ratio: 4/5;
+  position: relative; overflow: hidden;
+  border-radius: var(--radius); border: 1px solid var(--border);
+  padding: 18px;
+  background: var(--surface);
+  transition: transform .25s, border-color .25s;
+}
+.cat-tile:hover { transform: translateY(-4px); border-color: var(--border-strong); }
+.cat-tile::before {
+  content: ""; position: absolute; inset: 0;
+  background-size: cover; background-position: center;
+  opacity: .9; transition: transform .5s, opacity .25s;
+}
+.cat-tile:hover::before { transform: scale(1.06); }
+.cat-tile::after {
+  content: ""; position: absolute; inset: 0;
+  background: linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,0.75) 100%);
+}
+.cat-tile[data-cat="apparel"]::before  { background: linear-gradient(160deg, #2a2530, #14121a 70%); }
+.cat-tile[data-cat="home"]::before     { background: linear-gradient(160deg, #2c2620, #15110d 70%); }
+.cat-tile[data-cat="leather"]::before  { background: linear-gradient(160deg, #3a2a1d, #1a120a 70%); }
+.cat-tile[data-cat="scent"]::before    { background: linear-gradient(160deg, #1f2a2a, #0c1414 70%); }
+.cat-tile[data-cat="objects"]::before  { background: linear-gradient(160deg, #2a2230, #110d1a 70%); }
+
+.cat-label, .cat-count { position: relative; z-index: 1; display: block; }
+.cat-label {
+  font-family: var(--font-display); font-size: 26px; font-weight: 500;
+  position: absolute; left: 18px; bottom: 38px; z-index: 1;
+}
+.cat-count {
+  position: absolute; left: 18px; bottom: 18px; z-index: 1;
+  font-size: 12px; color: var(--text-dim); letter-spacing: 0.06em; text-transform: uppercase;
+}
+
+/* Featured */
+.filter-tabs { display: flex; gap: 6px; flex-wrap: wrap; }
+.tab {
+  background: transparent; color: var(--text-dim);
+  border: 1px solid var(--border); padding: 8px 16px;
+  border-radius: 999px; font-size: 13px; transition: all .2s;
+}
+.tab:hover { color: var(--text); border-color: var(--border-strong); }
+.tab.is-active { background: var(--text); color: var(--bg); border-color: var(--text); }
+
+.product-grid {
+  display: grid; gap: var(--gap);
+  grid-template-columns: repeat(4, minmax(0,1fr));
+}
+.product {
+  display: flex; flex-direction: column;
+  background: var(--surface);
+  border: 1px solid var(--border); border-radius: var(--radius);
+  overflow: hidden; transition: transform .25s, border-color .25s;
+  position: relative;
+}
+.product:hover { transform: translateY(-4px); border-color: var(--border-strong); }
+.product-art {
+  aspect-ratio: 4/5; position: relative; overflow: hidden;
+  background: #0e0e13;
+}
+.product-art::after {
+  content: ""; position: absolute; inset: 0;
+  background: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(0,0,0,0.4));
+  pointer-events: none;
+}
+.product-tag {
+  position: absolute; top: 12px; left: 12px; z-index: 2;
+  background: rgba(11,11,13,0.7); backdrop-filter: blur(8px);
+  border: 1px solid var(--border);
+  font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase;
+  padding: 5px 9px; border-radius: 999px;
+}
+.product-tag.tag-new { color: var(--accent); border-color: rgba(216,180,107,0.4); }
+.product-tag.tag-low { color: var(--danger); border-color: rgba(255,107,107,0.4); }
+
+.wishlist {
+  position: absolute; top: 10px; right: 10px; z-index: 2;
+  width: 36px; height: 36px; border-radius: 50%;
+  background: rgba(11,11,13,0.7); border: 1px solid var(--border);
+  color: var(--text); display: inline-flex; align-items: center; justify-content: center;
+  transition: background .2s, color .2s;
+}
+.wishlist:hover { background: var(--surface-2); color: var(--accent); }
+.wishlist[aria-pressed="true"] { color: var(--accent); }
+
+.product-body { padding: 16px 16px 18px; display: flex; flex-direction: column; gap: 6px; }
+.product-cat { font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-muted); }
+.product-title { font-size: 16px; font-weight: 600; margin: 0; }
+.product-foot { display: flex; align-items: center; justify-content: space-between; margin-top: 10px; gap: 8px; }
+.product-price { font-size: 15px; font-weight: 600; }
+.product-price .was { color: var(--text-muted); text-decoration: line-through; font-weight: 400; margin-left: 6px; font-size: 13px; }
+.add-btn {
+  background: var(--surface-2); color: var(--text);
+  border: 1px solid var(--border); padding: 8px 14px;
+  border-radius: 999px; font-size: 13px; transition: all .2s;
+}
+.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
+
+/* Product art variants */
+.art-1 { background: linear-gradient(160deg,#2a2530 0%,#0e0c14 100%); }
+.art-1::before { content:""; position:absolute; inset:20% 25%; background: radial-gradient(circle at 40% 35%, #5a4d6b, #1a1322 70%); border-radius: 50%; filter: blur(2px); }
+.art-2 { background: linear-gradient(160deg,#2a221a 0%,#0e0a06 100%); }
+.art-2::before { content:""; position:absolute; left:30%; right:30%; top:18%; bottom:18%; background: linear-gradient(180deg,#caa46a,#7a5b2c); border-radius: 6px; box-shadow: 0 30px 60px rgba(0,0,0,0.5); }
+.art-3 { background: linear-gradient(160deg,#1a2226 0%,#06090c 100%); }
+.art-3::before { content:""; position:absolute; inset:25% 30%; background: radial-gradient(circle, #3d4f5a, #0c1216 70%); border-radius: 50%; }
+.art-4 { background: linear-gradient(160deg,#2c2026 0%,#100810 100%); }
+.art-4::before { content:""; position:absolute; left:24%; right:24%; top:22%; bottom:22%; background: linear-gradient(160deg,#46303d,#22151c); border-radius: 12px; }
+.art-5 { background: linear-gradient(160deg,#1f2a23 0%,#080f0b 100%); }
