}
.news-form {
  display: flex; gap: 8px; flex-wrap: wrap;
  background: var(--surface); padding: 8px;
  border: 1px solid var(--border); border-radius: 999px;
  position: relative;
}
.news-form input {
  flex: 1; min-width: 200px;
  background: transparent; color: var(--text); border: 0;
  padding: 12px 18px; font-size: 15px;
}
.news-form input::placeholder { color: var(--text-muted); }
.news-form input:focus { outline: none; }
.form-message {
  position: absolute; left: 22px; bottom: -28px;
  font-size: 13px; margin: 0; min-height: 18px;
}
.form-message.is-error { color: var(--danger); }
.form-message.is-success { color: var(--success); }

/* Footer */
.site-footer { padding: 64px 0 24px; border-top: 1px solid var(--border); background: var(--bg-2); }
.footer-grid {
  display: grid; gap: 32px;
  grid-template-columns: 1.4fr repeat(3, minmax(0,1fr));
  margin-bottom: 48px;
}
.footer-brand .brand { font-size: 14px; margin: 0 0 12px; }
.footer-grid h3 {
  font-size: 12px; text-transform: uppercase; letter-spacing: 0.16em;
  color: var(--text); margin: 0 0 14px;
}
.footer-grid ul { display: flex; flex-direction: column; gap: 10px; }
.footer-grid a { color: var(--text-dim); font-size: 14px; }
.footer-grid a:hover { color: var(--accent); }
.footer-bottom {
  display: flex; justify-content: space-between; padding-top: 24px;
  border-top: 1px solid var(--border);
}

/* Toast */
.toast {
  position: fixed; bottom: 24px; left: 50%; transform: translate(-50%, 30px);
  background: var(--surface); color: var(--text);
  border: 1px solid var(--border-strong); border-radius: 999px;
  padding: 12px 20px; font-size: 14px;
  box-shadow: var(--shadow-2);
  opacity: 0; pointer-events: none;
  transition: opacity .25s, transform .25s;
  z-index: 100;
}
.toast.is-visible { opacity: 1; transform: translate(-50%, 0); }

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
  .cat-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
  .deals-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "feat feat"
      "a b"
      "c d";
  }
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "large large"
      "a b"
      "c c";
  }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .primary-nav { display: none; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-visual { order: -1; max-width: 100%; aspect-ratio: 5/4; }
  .product-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .cat-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .deals-grid {
    grid-template-columns: 1fr;
    grid-template-areas: "feat" "a" "b" "c" "d";
  }
  .editorial-grid {
    grid-template-columns: 1fr;
    grid-template-areas: "large" "a" "b" "c";
  }
  .editorial-grid > .ed-card:nth-of-type(4) { flex-direction: column; }
  .editorial-grid > .ed-card:nth-of-type(4) .ed-art { width: 100%; aspect-ratio: 4/3; }
  .news-inner { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; gap: 8px; }
  .hero-meta { grid-template-columns: 1fr; gap: 14px; }
  .countdown div { min-width: 48px; padding: 8px 10px; }
  .countdown span { font-size: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important; animation: none !important; scroll-behavior: auto !important;
  }
}
