+.editorial-grid > .ed-card:nth-of-type(4) .ed-body { flex: 1; }
+
+.ed-art { position: relative; aspect-ratio: 4/3; }
+.ed-large .ed-art { aspect-ratio: 4/5; }
+.ed-art-1 { background: linear-gradient(160deg,#262026 0%,#0a070b 100%); }
