// Wishlist + add to bag (delegation)
let cartCount = 2;
function initActions() {
  document.body.addEventListener("click", e => {
    const wish = e.target.closest(".wishlist");
    if (wish) {
      const pressed = wish.getAttribute("aria-pressed") === "true";
      wish.setAttribute("aria-pressed", String(!pressed));
      showToast(pressed ? "Removed from wishlist" : "Saved to wishlist");
      return;
    }
    const add = e.target.closest("[data-add]");
    if (add) {
      cartCount += 1;
      const cc = document.getElementById("cart-count");
      if (cc) cc.textContent = String(cartCount);
      const cb = document.getElementById("cart-btn");
      if (cb) cb.setAttribute("aria-label", `Shopping bag, ${cartCount} items`);
      showToast(`Added “${add.dataset.add}” to bag`);
    }
  });
}

// Toast
let toastTimer;
function showToast(msg) {
  const t = document.getElementById("toast");
  if (!t) return;
  t.textContent = msg;
  t.classList.add("is-visible");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("is-visible"), 2400);
}

// Countdown — counts down to a target ~2.5 days from now
function initCountdown() {
  const target = Date.now() + (2 * 24 * 60 + 14 * 60 + 36) * 60 * 1000 + 10 * 1000;
  const dEl = document.getElementById("cd-d");
  const hEl = document.getElementById("cd-h");
  const mEl = document.getElementById("cd-m");
  const sEl = document.getElementById("cd-s");
  if (!dEl) return;

  const pad = n => String(Math.max(0, n)).padStart(2, "0");
  function tick() {
    let diff = Math.max(0, target - Date.now());
    const d = Math.floor(diff / 86400000); diff -= d * 86400000;
    const h = Math.floor(diff / 3600000);  diff -= h * 3600000;
    const m = Math.floor(diff / 60000);    diff -= m * 60000;
    const s = Math.floor(diff / 1000);
    dEl.textContent = pad(d);
    hEl.textContent = pad(h);
    mEl.textContent = pad(m);
    sEl.textContent = pad(s);
  }
  tick();
  setInterval(tick, 1000);
}

// Newsletter
function initNewsletter() {
  const form = document.getElementById("news-form");
  const msg  = document.getElementById("news-message");
  const input = document.getElementById("news-email");
  if (!form) return;
  form.addEventListener("submit", e => {
    e.preventDefault();
    msg.classList.remove("is-error", "is-success");
    const value = (input.value || "").trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    if (!valid) {
      msg.textContent = "Please enter a valid email address.";
      msg.classList.add("is-error");
      input.focus();
      return;
    }
    msg.textContent = "Thank you — check your inbox to confirm.";
    msg.classList.add("is-success");
    input.value = "";
  });
}

// Footer year
function initYear() {
  const y = document.getElementById("year");
  if (y) y.textContent = new Date().getFullYear();
}

document.addEventListener("DOMContentLoaded", () => {
  renderProducts();
  initTabs();
  initActions();
  initCountdown();
  initNewsletter();
  initYear();
});
